};

pub mod config;

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Refresh stored funder groups and direct evidence using the current pipeline policy.
    RefreshFunderGroups,
    /// Show the latest ingestion key and directory path.
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Members {
        stage: String,
        #[arg(long)]
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::RefreshFunderGroups => {
            let config = DataConfig::from_env()?;
            let db = ExposedDatabase::new(&config.connection_string).await;
            let count = db.refresh_funder_groups().await?;
            println!("Refreshed funder groups: {count} identities");
        }
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => {
            let config = LoaderConfig::try_from(&config)?;
            let key = ingestion_key.unwrap_or_default();
            match ExposedDataPipeline::copy_latest_raw(&config.data_dir, key.clone()).await? {
                Some((path, source_key)) => {
                    println!("Source ingestion key: {source_key}");
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => match DeclarationIngestionStage::from_str(&stage)? {
            DeclarationIngestionStage::Fetch => {
                let config = DeclarationFetcherConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let api = ParliamentApiClient::new(config.batch_size)?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let fs = ExposedDataPipeline::new_with_ingestion_key(
                    &config.data_dir,
                    ingestion_key.unwrap_or_default(),
                )?;
                DeclarationFetcherService::new(db, api, fs)
                    .fetch_declarations()
                    .await?;
            }
            DeclarationIngestionStage::Resolve => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations resolve requires --ingestion-key")
                })?;
                let config = DeclarationResolverConfig::try_from(&config)?;
                let storage = ExposedDataPipeline::open_cleaned_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let scorer = WeldrsFunderScorer::new()?;
                let summary =
                    DeclarationResolverService::new(storage, scorer, config.candidate_budget)
                        .resolve_declarations()
                        .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Resolved declarations: {}",
                    std::path::absolute(config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("resolved/declarations")
                        .display()
                );
                println!("Observations: {}", summary.observations);
                println!("Funding occurrences: {}", summary.payments);
                println!("Pair decisions: {}", summary.pairs);
            }
            DeclarationIngestionStage::Load => {
                let ingestion_key = ingestion_key
                    .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
                let config = LoaderConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let storage = ExposedDataPipeline::open_resolved_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let summary = DeclarationLoaderService::new(storage, db)
                    .load_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                match summary.outcome {
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::Imported => {
                        println!("Loaded declarations: {}", summary.declarations);
                    }
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::AlreadyLoaded => {
                        println!("Run already loaded. Declarations: {}", summary.declarations);
                    }
                }
                println!("Resolved identities: {}", summary.funders);
                println!("Funding occurrences: {}", summary.funding_entries);
            }
            DeclarationIngestionStage::Clean => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations clean requires --ingestion-key")
                })?;
                let config = LoaderConfig::try_from(&config)?;
                let fs = ExposedDataPipeline::open_existing_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let summary = DeclarationCleanerService::new(fs)
                    .clean_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Cleaned declarations: {}",
                    std::path::absolute(&config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("cleaned/declarations")
                        .display()
                );
                println!("Member partitions: {}", summary.member_partitions);
                println!("Declarations: {}", summary.declarations);
                println!("Funding entries: {}", summary.funding_entries);
                println!("Funder observations: {}", summary.funders);
            }
        },
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}
//! Atomic projection of the pipeline's grouping policy into stored membership and evidence.

use sqlx::{Postgres, Transaction};

use crate::domain::models::{
    entity_ingestion::EntityIngestionError,
    funder::FunderId,
    funder_grouping::{GroupingFunder, build_funder_groups},
};

use super::ExposedDatabase;

impl ExposedDatabase {
    /// Rebuilds grouping for every persisted identity without replaying ingestion artifacts.
    ///
    /// # Errors
    /// Returns database or grouping-policy errors. A failed refresh preserves the previous projection.
    pub async fn refresh_funder_groups(&self) -> Result<usize, EntityIngestionError> {
        let mut tx = self.pool().begin().await.map_err(db_error)?;
        lock_declaration_loader(&mut tx).await?;
        let count = replace_funder_groups(&mut tx).await?;
        tx.commit().await.map_err(db_error)?;
        Ok(count)
    }
}

pub(super) async fn lock_declaration_loader(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<(), EntityIngestionError> {
    sqlx::query!("SELECT pg_advisory_xact_lock(hashtext('exposed.declaration-loader'))")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    Ok(())
}

pub(super) async fn replace_funder_groups(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<usize, EntityIngestionError> {
    let rows = sqlx::query!("SELECT id, funder_name FROM exposed.funders ORDER BY id")
        .fetch_all(&mut **tx)
        .await
        .map_err(db_error)?;
    let aliases = sqlx::query!("SELECT funder_id, funder_alias FROM exposed.funder_aliases ORDER BY funder_id, funder_alias")
        .fetch_all(&mut **tx).await.map_err(db_error)?;
    let mut by_id = std::collections::BTreeMap::<_, Vec<_>>::new();
    for alias in aliases {
        by_id
            .entry(alias.funder_id)
            .or_default()
            .push(alias.funder_alias);
    }
    let funders: Vec<_> = rows
        .into_iter()
        .map(|row| GroupingFunder {
            id: FunderId::new(row.id),
            name: row.funder_name,
            aliases: by_id.remove(&row.id).unwrap_or_default(),
        })
        .collect();
    let groups = build_funder_groups(&funders).map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_group_names")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_family_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    for (id, group) in &groups.memberships {
        sqlx::query!(
            "INSERT INTO exposed.funder_alias_groups (funder_id, group_id) VALUES ($1, $2)",
            id.value(),
            group.value()
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    }
    for name in groups.preferred_names {
        sqlx::query!("INSERT INTO exposed.funder_group_names (group_id, preferred_name, family_key) VALUES ($1, $2, $3)", name.group_id.value(), name.preferred_name.as_str(), name.family_key)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.alias_links {
        sqlx::query!("INSERT INTO exposed.funder_alias_links (left_funder_id, right_funder_id, normalized_alias, left_alias, right_alias) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.normalized_alias, link.left_alias, link.right_alias)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.family_links {
        sqlx::query!("INSERT INTO exposed.funder_family_links (left_funder_id, right_funder_id, family_key, left_name, right_name) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.family_key, link.left_name, link.right_name)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    Ok(groups.memberships.len())
}

